{
  "$schema": "../academic/tool-skill.schema.json",
  "schema_version": "1.0.0",
  "name": "academic-thesis-review",
  "slug": "academic-thesis-review",
  "version": "1.1.0",
  "description": "对学位论文规模的学术草稿进行分阶段多轮评审工作流，包含证据标签和修订优先级。",
  "author": {
    "name": "wmpluto",
    "github": "https://github.com/wmpluto"
  },
  "license": "MIT",
  "subtype": "review_workflow",
  "entry": {
    "primary": "SKILL.md",
    "supporting": [
      "USAGE_EXAMPLE.md",
      "README.md",
      "README.zh-CN.md"
    ]
  },
  "activation": {
    "triggers": [
      "review this thesis",
      "multi-round thesis review",
      "check chapter consistency",
      "review this dissertation"
    ],
    "required_inputs": [
      "draft_text"
    ],
    "optional_inputs": [
      "review_round",
      "thesis_type",
      "language",
      "prior_review_results"
    ]
  },
  "inputs": {
    "draft_text": {
      "type": "string",
      "description": "待评审的论文全文、章节内容或提取后的文本",
      "required": true
    },
    "review_round": {
      "type": "integer",
      "description": "评审轮次",
      "default": 1,
      "minimum": 1,
      "maximum": 3
    },
    "thesis_type": {
      "type": "string",
      "description": "论文类型，如 MBA、MEM、MPA 或其他应用研究学位论文"
    },
    "language": {
      "type": "string",
      "description": "评审语言",
      "default": "zh-CN"
    },
    "prior_review_results": {
      "type": "string",
      "description": "前一轮评审结果摘要或 review_results 内容"
    }
  },
  "outputs": {
    "review_report": {
      "type": "string",
      "description": "结构化评审意见，包含问题、证据标签和建议"
    },
    "severity_summary": {
      "type": "object",
      "description": "按严重级别汇总的问题统计"
    },
    "revision_priorities": {
      "type": "array",
      "description": "后续修订优先级列表",
      "items": {
        "type": "string"
      }
    }
  },
  "role_boundary": {
    "primary_job": "分阶段评审学位论文规模的草稿并生成证据标签的修订指导。",
    "not_responsible_for": [
      "文献检索",
      "通用文本总结",
      "逐句润色作为主要输出"
    ],
    "use_when": [
      "文档是学位论文规模或基于章节的",
      "用户需要分阶段评审而非快速编辑",
      "严重性标签和证据标签很重要"
    ],
    "do_not_use_when": [
      "用户只想要论文散文润色",
      "任务是短论文总结",
      "用户仍在收集文献而非评审草稿"
    ]
  },
  "artifacts": {
    "consumes": [
      "draft_manuscript",
      "paper_analysis"
    ],
    "produces": [
      "review_report"
    ]
  },
  "integrates_with": {
    "upstream": [
      "research-paper-writer",
      "academic-writing-refiner",
      "paper-summarize-academic"
    ],
    "downstream": []
  },
  "tags": [
    "academic-review",
    "thesis",
    "markdown",
    "openclaw",
    "claude-code"
  ],
  "category": "research-tools",
  "status": {
    "maturity": "documented",
    "evidence_level": "has_examples"
  }
}
